"""Kazakh captions: script clauses matched to whisper segment times of vo_kk.mp3 (whisper's Kazakh spelling is unreliable,
so only its timing is used); words inside a clause are timed by character position. Also writes tmap_kk.json
(Kazakh voice time -> Russian voice time anchors) so scene.html replays the Russian animation in step with the Kazakh voice."""
import json
SEG = [(0.00, 6.60, 'Тынық мұхитының шығыс бөлігін салқындатып тұратын алып табиғи желдеткіш кенеттен тоқтап қалды деп елестетіп көр.'),
 (6.74, 8.46, 'Дәл қазір осы болып жатыр.'), (8.56, 10.56, 'Бұл құбылыс Эль-Ниньо деп аталады,'), (10.58, 13.60, 'ал қазіргісін тіпті супер Эль-Ниньо деп атап жатыр.'),
 (14.02, 14.88, 'Мәселе мынада:'), (15.10, 18.56, 'бұл алып желдеткіш — пассаттар деп аталатын тұрақты желдер.'), (18.56, 20.54, 'Олар шығыстан батысқа қарай соғады.'),
 (20.76, 25.70, 'Ғасырлар бойы бұл желдер желкенді кемелерге Тынық мұхитын кесіп өтуге көмектескен.'),
 (25.82, 29.58, 'Олар жылы суды Индонезия мен солтүстік Аустралияға қарай айдайды,'), (29.58, 32.16, 'ал ол жерде су тропикалық нөсер әкеледі.'),
 (32.26, 36.04, 'Ал Перу мен оңтүстік Эквадор жағалауында су салқын күйінде қалады,'), (36.04, 38.38, 'сондықтан жағалаудың климаты құрғақ.'),
 (38.52, 41.30, 'Бірақ 2–7 жыл сайын пассаттар әлсірейді,'), (41.42, 43.92, 'ал жылы су қайтадан шығысқа қарай жайылады.'),
 (44.04, 46.80, 'Мұнда су қалыптыдан 1–2 градусқа жылы болады.'), (47.02, 50.96, 'Бүкіл әлемде ауа райын астан-кестең етуге осының өзі жеткілікті.'),
 (51.04, 52.84, 'Канадаға бұл жылы қыс әкеледі,'), (53.06, 55.00, 'АҚШ-тың оңтүстігіне — қатты жаңбыр,'), (55.08, 57.78, 'Оңтүстік Американың бір бөлігіне — су тасқыны,'),
 (57.88, 61.08, 'ал Индонезия мен Аустралия құрғақшылықтан зардап шегеді.'), (61.50, 66.20, '1870-жылдары қуатты Эль-Ниньо ашаршылықтың себептерінің бірі болды.'),
 (66.30, 69.20, 'Ол Жер халқының шамамен 3%-ының өмірін қиды.'), (69.20, 74.86, 'Ал қазір ғалымдар қазіргі Эль-Ниньо бақылау тарихындағы ең күштісі болуы мүмкін деп есептейді:'),
 (74.88, 78.92, 'Тынық мұхитының шығыс бөлігінде су 3 градустан артық жылынуы мүмкін.'), (79.14, 83.52, 'Мұхит жылуды атмосфераға береді де, бүкіл планетаның температурасын көтереді.'),
 (83.70, 87.40, 'Ал 2027 жыл тарихтағы ең ыстық жыл болуы мүмкін.'), (87.52, 91.44, 'Айтпақшы, мұндай сұрақтар географиядан ҰБТ-да жиі кездеседі.'),
 (91.52, 94.52, 'Біз географиядан ҰБТ-ға арналған гайд дайындадық.'), (94.58, 97.18, 'Оны алғың келсе, комментарийге «гео» деп жаз.')]
toks = []
for s, e, text in SEG:
    ws = text.replace(' — ', ' ').split(); n = sum(len(w) + 1 for w in ws); p = 0
    for w in ws: toks.append([s + (e - s) * p / n, s + (e - s) * (p + len(w)) / n, w]); p += len(w) + 1
caps, cur = [], []
for t in toks:
    cur.append(t); L = len(' '.join(x[2] for x in cur))
    if t[2][-1] in '.?!:,' and L > 2 or L > 16 or len(cur) == 3: caps.append(cur); cur = []
if cur: caps.append(cur)
out = [{'s': c[0][0], 'e': c[-1][1], 't': ' '.join(x[2] for x in c).rstrip(',.:')} for c in caps]
for a, b in zip(out, out[1:]): a['e'] = min(b['s'], a['e'] + 0.4)
json.dump(out, open('captions_kk.json', 'w'), ensure_ascii=False)
# [kk time, ru time] anchors (sentence starts and key words in both voices)
TM = [[0, 0], [6.74, 6.88], [8.56, 9.62], [11.92, 12.6], [14.02, 14.06], [15.10, 14.9], [18.56, 19.34], [20.76, 21.22], [25.82, 24.82], [26.8, 26.4],
 [28.16, 27.48], [29.58, 28.16], [30.7, 28.94], [32.26, 30.18], [33.48, 31.4], [36.04, 33.54], [38.52, 35.4], [41.42, 38.06], [44.04, 40.7], [45.34, 41.84],
 [47.02, 43.82], [48.34, 45.84], [51.04, 47.22], [53.06, 49.42], [55.08, 51.44], [57.88, 53.16], [61.50, 56.44], [66.30, 61.16], [67.82, 62.42],
 [69.20, 64.66], [74.88, 70.74], [76.74, 74.24], [79.14, 75.3], [83.70, 79.28], [87.52, 83.68], [90.04, 86.14], [91.52, 87.58], [93.52, 88.28],
 [94.58, 90.14], [95.76, 91.94], [96.42, 92.7], [97.44, 93.6], [99.6, 95.76]]
json.dump(TM, open('tmap_kk.json', 'w'))
json.dump({'scenes': [{'id': 'all', 'end': 99.2}]}, open('timeline_kk.json', 'w'))
print(len(out)); print(' | '.join(c['t'] for c in out))
